### 4. No authentication / authorization on `/users` (A01: Broken Access Control + A02 indirectly)
`/users` returns PII (names + email addresses) to *anyone*. Even though the data is currently hard-coded, the endpoint pattern is a textbook BOLA/IDOR setup once it's wired to a DB.

**Recommendation:** Require auth and scope results.
```js
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const header = req.headers.authorization || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'] });
    next();
  } catch {
    return res.status(401).json({ error: 'unauthorized' });
  }
