  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com' },
];
const toPublicUser = (u) => ({ id: u.id, name: u.name });

app.get('/users', apiLimiter, requireAuth, (req, res) => {
  res.json(USERS.map(toPublicUser));
});

