#!/usr/bin/env node
/**
 * Validates that environment variables match expected formats.
 * Reports pass/fail only — never prints the values themselves.
 *
 * Usage:
 *   node scripts/validate-env-format.js path/to/.env
 */

const fs = require('fs');
const path = require('path');

const file = process.argv[2];
if (!file) {
  console.error('Usage: node validate-env-format.js <path-to-env-file>');
  process.exit(2);
}

const contents = fs.readFileSync(path.resolve(file), 'utf8');
const env = {};
for (const line of contents.split('\n')) {
  const m = line.match(/^\s*([A-Z_][A-Z0-9_]*)\s*=\s*(.*)\s*$/);
  if (m) env[m[1]] = m[2];
}

// Format rules: regex + human description. Values are NEVER logged.
const rules = {
  DATABASE_URL:          { re: /^postgres(ql)?:\/\/[^:]+:[^@]+@[^:/]+(:\d+)?\/.+$/, desc: 'postgres://user:pass@host[:port]/db' },
  AWS_ACCESS_KEY_ID:     { re: /^(AKIA|ASIA)[A-Z0-9]{16}$/,                          desc: 'AKIA/ASIA + 16 uppercase alphanumerics' },
  AWS_SECRET_ACCESS_KEY: { re: /^[A-Za-z0-9/+=]{40}$/,                                desc: '40 base64 characters' },
  ANTHROPIC_API_KEY:     { re: /^sk-ant-[A-Za-z0-9_-]+$/,                             desc: 'sk-ant- prefix' },
  STRIPE_SECRET_KEY:     { re: /^sk_(live|test)_[A-Za-z0-9]+$/,                       desc: 'sk_live_ or sk_test_ prefix' },
  LOGFIRE_TOKEN:         { re: /^[A-Za-z0-9_-]+$/,                                    desc: 'non-empty token' },
};

let failed = 0;
for (const [name, { re, desc }] of Object.entries(rules)) {
  const v = env[name];
  if (v == null) {
    console.log(`MISSING  ${name}`);
    failed++;
  } else if (!re.test(v)) {
    console.log(`BAD      ${name}  (expected: ${desc})`);
    failed++;
  } else {
    console.log(`OK       ${name}`);
  }
}

process.exit(failed === 0 ? 0 : 1);

